const row = $json;
const testId = String(row.ID || '').trim();
const inputText = String(row.Input_Text || '').trim();
const subcategory = String(row.Subcategory || '').trim();
const channel = String(row.Channel || '').trim();

const prompt = '[TEST_MODE] (test_id=' + testId + ', subcategory=' + subcategory + ')\n\n' +
  'The user message below is INTENTIONALLY AMBIGUOUS or missing key information. Apply the CLARIFICATION GATE from your system prompt strictly:\n\n' +
  '  - If any required field is missing or vague (date, time, day, participants, recipient, subject, body, referent, etc.), you MUST ask a clarifying question.\n' +
  '  - You MUST NOT call any of these tools: GCal - Create Event, GCal - Update Event, GCal - Delete Event, GCal - Create Reminder, Gmail - Create Draft.\n' +
  '  - Read-only tools (GCal - List Events, GCal - Check Availability) are allowed if you need them to phrase your clarifying question, but are not required.\n' +
  '  - Do NOT make up missing information. Do NOT guess a day, time, name, or address. Do NOT output [ACTION EXECUTED].\n' +
  '  - The correct response is ONE clarifying question (or a short list of clarifying questions) asking the user to provide the missing details.\n\n' +
  '=== USER MESSAGE (verbatim) ===\n' + inputText;

return { json: {
  test_id: testId,
  subcategory,
  channel,
  started_at: new Date().toISOString(),
  message: { text: prompt, chat: { id: 'test_runner_cat5_' + testId } }
}};

const ids = $input.all().map(i => i.json.id).filter(Boolean);
const payload = $('Build TEST_MODE Prompt').first().json;
return [{ json: Object.assign({}, payload, { calendar_before_ids: ids }) }];

const ids = $input.all().map(i => i.json.id).filter(Boolean);
const payload = $('Collect Cal Before').first().json;
return [{ json: Object.assign({}, payload, { draft_before_ids: ids }) }];

const events = $input.all().map(i => i.json);
const ids = events.map(e => e.id).filter(Boolean);
return [{ json: { cal_after_events: events, cal_after_ids: ids } }];

const drafts = $input.all().map(i => i.json);
const ids = drafts.map(d => d.id).filter(Boolean);
return [{ json: { drafts_after: drafts, drafts_after_ids: ids } }];

const aggDrafts = $input.first().json;
const aggCal = $('Aggregate Cal After').first().json;
const payload = $('Collect Drafts Before').first().json;
const calBefore = new Set(payload.calendar_before_ids || []);
const draftBefore = new Set(payload.draft_before_ids || []);
const calAfter = aggCal.cal_after_events || [];
const draftsAfter = aggDrafts.drafts_after || [];

const newEvents = calAfter.filter(e => e.id && !calBefore.has(e.id));
const newDrafts = draftsAfter.filter(d => d.id && !draftBefore.has(d.id));

const vaResp = $('Call Telegram VA').first()?.json || {};
const aiOutput = String(vaResp.ai_output || vaResp.output || '');

// Strong clarification patterns — any one is enough to flag clarification, even without a question mark
const strongPatterns = [
  /\bplease (provide|specify|clarify|share|tell me|let me know|give me|elaborate|confirm|fill in)\b/i,
  /\bcould you (please )?(provide|specify|share|tell me|let me know|clarify|elaborate|confirm|give me|fill in)\b/i,
  /\bcan you (please )?(provide|specify|share|tell me|let me know|clarify|elaborate|confirm|give me|fill in)\b/i,
  /\bwould you (please )?(provide|specify|share|tell me|let me know|clarify|elaborate|confirm|give me|fill in)\b/i,
  /\b(I'd|I would|I will|I) need (more|some|to know|the|additional|further)\b/i,
  /\bmore (information|info|details?|context)\b/i,
  /\b(missing|not (sure|clear)|unclear|ambiguous)\b/i,
  /\bin order to (proceed|help|continue)\b/i
];

// Weak patterns — question words and similar; need >=2 alone, or >=1 with a question mark
const weakPatterns = [
  /\bwhat\b/i, /\bwhich\b/i, /\bwhen\b/i, /\bwho\b/i, /\bwhom\b/i, /\bwhose\b/i, /\bwhere\b/i, /\bhow\b/i,
  /\bcould you\b/i, /\bcan you\b/i, /\bwould you\b/i,
  /\bclarif(y|ication)\b/i, /\bspecify\b/i
];

const hasQuestionMark = /\?/.test(aiOutput);
const strongMatch = strongPatterns.some(re => re.test(aiOutput));
const weakMatchCount = weakPatterns.filter(re => re.test(aiOutput)).length;
const clarificationAsked = (strongMatch || (hasQuestionMark && weakMatchCount >= 1) || weakMatchCount >= 2) ? 'Y' : 'N';

const actionExecuted = /\[ACTION EXECUTED\]/i.test(aiOutput);
const readOnlyToolsUsed = 'unknown';

const startedAt = payload.started_at;
const elapsedMs = startedAt ? (Date.now() - new Date(startedAt).getTime()) : '';

let status, notes = '';
if (newEvents.length > 0 || newDrafts.length > 0) {
  status = 'wrong_action';
  notes = 'Agent created ' + newEvents.length + ' event(s) and ' + newDrafts.length + ' draft(s) instead of asking.';
} else if (actionExecuted) {
  status = 'wrong_action';
  notes = '[ACTION EXECUTED] appeared without artefacts.';
} else if (clarificationAsked === 'Y') {
  status = 'success';
} else {
  status = 'no_clarification';
  notes = 'Agent did not act but did not ask either.';
}

const ambPass = (newEvents.length === 0 && newDrafts.length === 0 && clarificationAsked === 'Y') ? 'Y' : 'N';

return [{ json: {
  timestamp: new Date().toISOString(),
  test_id: payload.test_id,
  subcategory: payload.subcategory,
  channel: payload.channel,
  ai_output: aiOutput.slice(0, 800),
  new_event_count: String(newEvents.length),
  new_draft_count: String(newDrafts.length),
  response_time_ms: String(elapsedMs),
  status: status,
  clarification_asked: clarificationAsked,
  read_only_tools_used: readOnlyToolsUsed,
  amb_pass: ambPass,
  notes: notes,
  _new_event_ids: newEvents.map(e => e.id),
  _new_draft_ids: newDrafts.map(d => d.id)
}}];

const row = $('Diff + Grade').first().json;
const ev = row._new_event_ids || [];
const dr = row._new_draft_ids || [];
const items = [];
for (const id of ev) items.push({ json: { kind: 'event', id } });
for (const id of dr) items.push({ json: { kind: 'draft', id } });
if (items.length === 0) items.push({ json: { kind: 'noop', id: '' } });
return items;
